pub fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Each special guest needs one cookie from each pile.
    // Ensure each pile has at least m cookies for the special guests.
    if a < m || b < m {
        return false;
    }
    // After reserving m cookies from each pile for the special guests,
    // we have (a + b - 2*m) cookies left to serve n regular guests.
    // We check (a + b) >= (n + 2*m) using a wider integer type to avoid overflow.
    let total: u16 = a as u16 + b as u16;
    let required: u16 = n as u16 + 2 * (m as u16);
    total >= required
}

